      <td>
        <button type="button" data-testid="person-statement" disabled={take.isPending} onClick={() => take.mutate()}>
          Statement
        </button>
        {take.isError && (
          <span data-testid="person-error" role="alert">
            {' '}
            Could not take this statement.
          </span>
        )}
      </td>
    </>
  );
}

